<?php $pageTitle='Produtos'; require_once __DIR__.'/../../includes/header.php';
$action=$_GET['action']??''; $id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0); $sku=trim($_POST['sku']??''); $nome=trim($_POST['nome']??''); $categoria=trim($_POST['categoria']??''); $preco_custo=trim($_POST['preco_custo']??''); $preco_venda=trim($_POST['preco_venda']??''); $estoque_atual=trim($_POST['estoque_atual']??''); $estoque_minimo=trim($_POST['estoque_minimo']??''); $status=trim($_POST['status']??''); if($id){$st=$pdo->prepare('UPDATE produtos SET sku=?,nome=?,categoria=?,preco_custo=?,preco_venda=?,estoque_atual=?,estoque_minimo=?,status=? WHERE id=?');$st->execute([$sku,$nome,$categoria,$preco_custo,$preco_venda,$estoque_atual,$estoque_minimo,$status,$id]);flash('ok','Registro atualizado.');}else{$st=$pdo->prepare('INSERT INTO produtos (sku,nome,categoria,preco_custo,preco_venda,estoque_atual,estoque_minimo,status) VALUES (?,?,?,?,?,?,?,?)');$st->execute([$sku,$nome,$categoria,$preco_custo,$preco_venda,$estoque_atual,$estoque_minimo,$status]);flash('ok','Registro cadastrado.');} header('Location: index.php');exit; }
if($action==='excluir'&&$id){$pdo->prepare('DELETE FROM produtos WHERE id=?')->execute([$id]);flash('ok','Registro removido.');header('Location: index.php');exit;}
$edit=null;if($action==='editar'&&$id){$st=$pdo->prepare('SELECT * FROM produtos WHERE id=?');$st->execute([$id]);$edit=$st->fetch();} $rows=$pdo->query('SELECT * FROM produtos ORDER BY id DESC')->fetchAll(); ?>
<div class="panel mb-3"><div class="panel-title"><h3>Gestão de produtos</h3><button class="btn btn-dark btn-sm" data-bs-toggle="collapse" data-bs-target="#form"><i class="bi bi-plus-lg"></i> Novo</button></div><div class="collapse <?= $edit?'show':'' ?>" id="form"><form method="post" class="row g-3 pt-2"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="col-md-4"><label class="form-label">SKU</label><input class="form-control" type="text" name="sku" value="<?=e($edit['sku']??'')?>"></div><div class="col-md-4"><label class="form-label">Produto</label><input class="form-control" type="text" name="nome" value="<?=e($edit['nome']??'')?>"></div><div class="col-md-4"><label class="form-label">Categoria</label><input class="form-control" type="text" name="categoria" value="<?=e($edit['categoria']??'')?>"></div><div class="col-md-4"><label class="form-label">Custo</label><input class="form-control" type="number" step="0.01" name="preco_custo" value="<?=e($edit['preco_custo']??'')?>"></div><div class="col-md-4"><label class="form-label">Venda</label><input class="form-control" type="number" step="0.01" name="preco_venda" value="<?=e($edit['preco_venda']??'')?>"></div><div class="col-md-4"><label class="form-label">Estoque</label><input class="form-control" type="number" step="0.01" name="estoque_atual" value="<?=e($edit['estoque_atual']??'')?>"></div><div class="col-md-4"><label class="form-label">Mínimo</label><input class="form-control" type="number" step="0.01" name="estoque_minimo" value="<?=e($edit['estoque_minimo']??'')?>"></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="ATIVO" <?=($edit['status']??'')==='ATIVO'?'selected':''?>>ATIVO</option><option value="INATIVO" <?=($edit['status']??'')==='INATIVO'?'selected':''?>>INATIVO</option></select></div><div class="col-12"><button class="btn btn-dark">Salvar</button> <a class="btn btn-light" href="index.php">Cancelar</a></div></form></div></div><div class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>#</th><th>SKU</th><th>Produto</th><th>Categoria</th><th>Custo</th><th>Venda</th><th>Estoque</th><th>Mínimo</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['sku'])?></td><td><?=e($r['nome'])?></td><td><?=e($r['categoria'])?></td><td><?=money($r['preco_custo'])?></td><td><?=money($r['preco_venda'])?></td><td><?=e($r['estoque_atual'])?></td><td><?=e($r['estoque_minimo'])?></td><td><?=e($r['status'])?></td><td class="text-end"><a class="btn btn-light btn-sm" href="?action=editar&id=<?=$r['id']?>"><i class="bi bi-pencil"></i></a> <a class="btn btn-light btn-sm" data-confirm="Excluir este registro?" href="?action=excluir&id=<?=$r['id']?>"><i class="bi bi-trash"></i></a></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>